30: function renderFileRows(){const list=document.getElementById('fileRows');if(!list)return;list.innerHTML=selectedFiles.map((f,i)=>`<div class="file-row"><span class="file-badge">${f.type.startsWith('image/')?'IMG':'PDF'}</span><span class="file-meta"><strong>${escapeHTML(f.name)}</strong><span>${formatBytes(f.size)}</span></span><button class="file-remove" data-remove="${i}" aria-label="Hapus ${escapeHTML(f.name)}">×</button></div>`).join('');list.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{selectedFiles.splice(+b.dataset.remove,1);renderFileRows()}));document.querySelectorAll('.option-chip').forEach(l=>l.addEventListener('click',()=>{let radio=l.querySelector('input');if(radio){document.querySelectorAll(`input[name="${radio.name}"]`).forEach(r=>r.closest('.option-chip').classList.remove('active'));l.classList.add('active');radio.checked=true}}))}
