32: function addFiles(files){let valid=[...files].filter(f=>activeTool.input==='images'?f.type.startsWith('image/'):f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf'));if(!valid.length&&files.length)showError(activeTool.input==='images'?'Pilih file gambar PNG, JPG, atau WEBP.':'Pilih file PDF yang valid.');else{if(activeTool.input!=='pdf-multiple'&&activeTool.input!=='images')selectedFiles=[];selectedFiles.push(...valid.filter(f=>!selectedFiles.some(old=>old.name===f.name&&old.size===f.size)));renderFileRows();document.getElementById('modalError').classList.remove('show')}}
