37: function parsePages(str,total){if(!str.trim())throw Error('Masukkan rentang halaman terlebih dahulu.');const pages=[];for(const part of str.split(',')){let m=part.trim().match(/^(\d+)(?:\s*[-–]\s*(\d+))?$/);if(!m)throw Error(`Format rentang “${part.trim()}” tidak valid.`);let a=+m[1],b=+(m[2]||m[1]);if(a<1||b<a||b>total)throw Error(`Rentang ${part.trim()} di luar jumlah halaman (1–${total}).`);for(let n=a;n<=b;n++)if(!pages.includes(n-1))pages.push(n-1)}return pages}
38: async function readPDF(file){const bytes=await file.arrayBuffer();return {bytes,doc:await PDFDocument.load(bytes)}}
39: async function rasterize(file,quality){const bytes=new Uint8Array(await file.arrayBuffer());const pdf=await pdfjsLib.getDocument({data:bytes}).promise;const out=await PDFDocument.create();const settings={low:{scale:0.8,jpeg:0.48},medium:{scale:1.15,jpeg:0.68},high:{scale:1.5,jpeg:0.84}}[quality];for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),viewport=page.getViewport({scale:settings.scale}),canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{alpha:false});canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await page.render({canvasContext:ctx,viewport,background:'#ffffff'}).promise;const jpg=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',settings.jpeg));if(!jpg)throw Error('Gagal merender halaman. Coba gunakan file lain.');const image=await out.embedJpg(await jpg.arrayBuffer()),size=page.getViewport({scale:1});const pdfPage=out.addPage([size.width,size.height]);pdfPage.drawImage(image,{x:0,y:0,width:size.width,height:size.height});canvas.width=1;canvas.height=1}return out.save({useObjectStreams:true})}
