41: switch(activeTool.id){case'split':{const {doc}=await readPDF(selectedFiles[0]),total=doc.getPageCount(),parts=document.getElementById('rangeField').value.split(',').map(s=>s.trim()).filter(Boolean);if(!parts.length)throw Error('Masukkan rentang halaman terlebih dahulu.');const files=[];for(let i=0;i<parts.length;i++){const ids=parsePages(parts[i],total),piece=await PDFDocument.create(),copied=await piece.copyPages(doc,ids);copied.forEach(p=>piece.addPage(p));files.push({name:`${filenameBase(selectedFiles[0].name)}-halaman-${parts[i].replace(/\s/g,'')}.pdf`,data:await piece.save()})}if(files.length===1)download(files[0].data,files[0].name);else{const zipped={};for(const f of files)zipped[f.name]=new Uint8Array(f.data);download(fflate.zipSync(zipped,{level:6}),`${filenameBase(selectedFiles[0].name)}-hasil-pisah.zip`,'application/zip')}break}
42: case'extract':{const {doc}=await readPDF(selectedFiles[0]),ids=parsePages(document.getElementById('rangeField').value,doc.getPageCount()),piece=await PDFDocument.create(),pages=await piece.copyPages(doc,ids);pages.forEach(p=>piece.addPage(p));download(await piece.save(),`${filenameBase(selectedFiles[0].name)}-ekstrak.pdf`);break}
