24:function renderTools(filter=''){let found=tools.filter(t=>(t.title+' '+t.description).toLowerCase().includes(filter.toLowerCase()));grid.innerHTML=found.length?found.map(t=>`<button class="tool-card" data-tool="${t.id}"><span class="tool-top"><span class="tool-icon ${t.color}">${icon(t.icon)}</span><span class="tool-arrow">↗</span></span>${t.tag?`<span class="tool-tag ${t.tag==='BARU'?'new':''}">${t.tag}</span>`:''}<h3>${t.title}</h3><p>${t.description}</p></button>`).join(''):'<div class="empty-search">Tidak ada alat yang cocok. Coba kata kunci lain.</div>';grid.querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>openTool(b.dataset.tool)))}renderTools();
28:function openTool(id){activeTool=tools.find(t=>t.id===id);if(!activeTool)return;selectedFiles=[];document.getElementById('modalIcon').innerHTML=icon(activeTool.icon);document.getElementById('modalIcon').className=`modal-top-icon ${activeTool.color}`;document.getElementById('modalEyebrow').textContent='ALAT PDF';document.getElementById('modalTitle').textContent=activeTool.title;document.getElementById('modalDescription').textContent=activeTool.detail;document.getElementById('modalError').classList.remove('show');document.getElementById('modalContent').innerHTML=modalFields(activeTool);document.getElementById('modalAction').disabled=false;document.getElementById('modalAction').innerHTML=`<span>${activeTool.action}</span><span>↗</span>`;fileInput.value='';fileInput.multiple=activeTool.input==='pdf-multiple'||activeTool.input==='images';fileInput.accept=activeTool.input==='images'?'image/png,image/jpeg,image/webp':'.pdf,application/pdf';renderFileRows();modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';wireDropzone()}
