35:function renderFileRows(){const list=document.getElementById('fileRows');if(!list)return;list.innerHTML=selectedFiles.map((f,i)=>`<div class="file-row"><span class="file-badge">${f.type.startsWith('image/')?'IMG':'PDF'}</span><span class="file-meta"><strong>${escapeHTML(f.name)}</strong><span>${formatBytes(f.size)}</span></span><button class="file-remove" data-remove="${i}" aria-label="Hapus ${escapeHTML(f.name)}">×</button></div>`).join('');list.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{selectedFiles.splice(+b.dataset.remove,1);renderFileRows()}));document.querySelectorAll('.option-chip').forEach(l=>l.addEventListener('click',()=>{let radio=l.querySelector('input');if(radio){document.querySelectorAll(`input[name="${radio.name}"]`).forEach(r=>r.closest('.option-chip').classList.remove('active'));l.classList.add('active');radio.checked=true}}))}
37:function addFiles(files){let valid=[...files].filter(f=>activeTool.input==='images'?f.type.startsWith('image/'):f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf'));if(!valid.length&&files.length)showError(activeTool.input==='images'?'Pilih file gambar PNG, JPG, atau WEBP.':'Pilih file PDF yang valid.');else{if(activeTool.input!=='pdf-multiple'&&activeTool.input!=='images')selectedFiles=[];selectedFiles.push(...valid.filter(f=>!selectedFiles.some(old=>old.name===f.name&&old.size===f.size)));renderFileRows();document.getElementById('modalError').classList.remove('show')}}
42:function parsePages(str,total){if(!str.trim())throw Error('Masukkan rentang halaman terlebih dahulu.');const pages=[];for(const part of str.split(',')){let m=part.trim().match(/^(\d+)(?:\s*[-–]\s*(\d+))?$/);if(!m)throw Error(`Format rentang “${part.trim()}” tidak valid.`);let a=+m[1],b=+(m[2]||m[1]);if(a<1||b<a||b>total)throw Error(`Rentang ${part.trim()} di luar jumlah halaman (1–${total}).`);for(let n=a;n<=b;n++)if(!pages.includes(n-1))pages.push(n-1)}return pages}
45:async function processTool(){if(!selectedFiles.length){showError(activeTool.input==='images'?'Pilih setidaknya satu gambar.':'Pilih file PDF terlebih dahulu.');return}if(activeTool.id==='merge'&&selectedFiles.length<2){showError('Tambahkan minimal dua file PDF untuk digabungkan.');return}const button=document.getElementById('modalAction');button.disabled=true;button.innerHTML='<span>Sedang memproses…</span><span>◌</span>';document.getElementById('modalError').classList.remove('show');try{let out,compressionFallback=false;
46:switch(activeTool.id){case'split':{const {doc}=await readPDF(selectedFiles[0]),total=doc.getPageCount(),parts=document.getElementById('rangeField').value.split(',').map(s=>s.trim()).filter(Boolean);if(!parts.length)throw Error('Masukkan rentang halaman terlebih dahulu.');const files=[];for(let i=0;i<parts.length;i++){const ids=parsePages(parts[i],total),piece=await PDFDocument.create(),copied=await piece.copyPages(doc,ids);copied.forEach(p=>piece.addPage(p));files.push({name:`${filenameBase(selectedFiles[0].name)}-halaman-${parts[i].replace(/\s/g,'')}.pdf`,data:await piece.save()})}if(files.length===1)download(files[0].data,files[0].name);else{const zipped={};for(const f of files)zipped[f.name]=new Uint8Array(f.data);download(fflate.zipSync(zipped,{level:6}),`${filenameBase(selectedFiles[0].name)}-hasil-pisah.zip`,'application/zip')}break}
47:case'extract':{const {doc}=await readPDF(selectedFiles[0]),ids=parsePages(document.getElementById('rangeField').value,doc.getPageCount()),piece=await PDFDocument.create(),pages=await piece.copyPages(doc,ids);pages.forEach(p=>piece.addPage(p));download(await piece.save(),`${filenameBase(selectedFiles[0].name)}-ekstrak.pdf`);break}
